import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int r = nextInt(), s = nextInt();
        long[] req = new long[r];
        for (int i = 0; i < r; i++) req[i] = nextLong();
        int bestIndex = -1;
        long bestWaste = 0;
        for (int index = 1; index <= s; index++) {
            int c = nextInt();
            long[] box = new long[c];
            for (int i = 0; i < c; i++) box[i] = nextLong();
            Arrays.sort(box);
            long total = 0;
            boolean feasible = true;
            for (long need : req) {
                // Smallest container that fits (lower_bound) gives the least waste for this order.
                int lo = 0, hi = c;
                while (lo < hi) {
                    int mid = (lo + hi) >>> 1;
                    if (box[mid] < need) lo = mid + 1;
                    else hi = mid;
                }
                if (lo == c) {
                    feasible = false;
                    break;
                }
                total += box[lo] - need;
            }
            if (feasible && (bestIndex == -1 || total < bestWaste)) {
                bestIndex = index;
                bestWaste = total;
            }
        }
        System.out.println(bestIndex);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	r, s := int(nextInt()), int(nextInt())
	req := make([]int64, r)
	for i := range req {
		req[i] = nextInt()
	}
	bestIndex, bestWaste := -1, int64(0)
	for index := 1; index <= s; index++ {
		box := make([]int64, nextInt())
		for i := range box {
			box[i] = nextInt()
		}
		slices.Sort(box)
		var total int64
		feasible := true
		for _, need := range req {
			// Smallest container that fits gives the least waste for this order.
			p, _ := slices.BinarySearch(box, need)
			if p == len(box) {
				feasible = false
				break
			}
			total += box[p] - need
		}
		if feasible && (bestIndex == -1 || total < bestWaste) {
			bestIndex, bestWaste = index, total
		}
	}
	fmt.Println(bestIndex)
}
